import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"素数筛","description":"","frontmatter":{"title":"素数筛","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sieve.md","filePath":"cs/sieve.md","lastUpdated":1789023840000}'),c={name:"cs/sieve.md"};function _(m,a,E,A,u,f){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="素数筛" tabindex="-1">素数筛 <a class="header-anchor" href="#素数筛" aria-label="Permalink to &quot;素数筛&quot;">​</a></h1><div class="epigraph"><p>埃氏筛用每个素数划掉倍数，$O(n\\log\\log n)$ 列出 $[1,n]$ 的素数；线性筛让每个合数只被最小素因子划一次。</p><footer>—— 据 Eratosthenes（古典）；线性筛见现代数论算法教材；CLRS 第 31 章整理</footer></div><p>上一课<a href="/cs/interior-point">内点法</a>收束连续优化。主干<a href="/cs/miller-rabin">素性</a>测单个 \\(n\\)。缺口是<strong>区间内全体素数</strong>：筛。不重写 Miller–Rabin。后课欧拉函数在筛的数组上填。接<a href="/cs/prime-generation">素数生成</a>只当密码侧单个大素数，本课是小 \\(n\\) 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>埃氏：从 \\(2\\) 到 \\(\\sqrt n\\)，是素数则划 \\(p^2,p^2+p,\\ldots\\)。时间 \\(\\sum_{p\\le n}n/p=\\Theta(n\\log\\log n)\\)。空间 \\(O(n)\\)。线性筛（Euler）：维护最小素因子，对每个 \\(i\\) 乘尚未超过 \\(minp[i]\\) 的素数，合数只被最小 \\(p\\) 划到，真正 \\(O(n)\\)。</p><p>分段筛：内存放不下 \\([1,n]\\) 时按块筛，空间 \\(O(\\sqrt n+\\text{块})\\)。</p><p>缺口是列表，不是单次素性测试。</p><h3 id="筛不是因式分解" tabindex="-1">筛不是因式分解 <a class="header-anchor" href="#筛不是因式分解" aria-label="Permalink to &quot;筛不是因式分解&quot;">​</a></h3><p>筛给小素数表。分解大 \\(n\\) 是后课 Pollard rho。不要用埃氏筛分解 256 位整数。</p><p><span class="marginnote">CLRS 31 谈数论算法，筛是预备。线性筛同时可积性函数。后课 \\(\\varphi\\)、\\(\\mu\\) 就地筛出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>布尔数组或比特压。埃氏或线性。需要 \\(10^7\\) 内表时线性筛顺便 <code>minp</code>。更大 \\(n\\) 分段。</p>',12)),(e(),s(h,null,{default:r(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E4%B8%8A%E9%99%90%20n%22%5D%20--%3E%20ERA%5B%22%E5%9F%83%E6%B0%8F%EF%BC%9A%E7%B4%A0%E6%95%B0%E5%88%92%E5%80%8D%E6%95%B0%22%5D%0A%20%20N%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%EF%BC%9A%E6%9C%80%E5%B0%8F%E7%B4%A0%E5%9B%A0%E5%AD%90%22%5D%0A%20%20LIN%20--%3E%20TAB%5B%22%E7%B4%A0%E6%95%B0%E8%A1%A8%22%5D%0A%20%20ERA%20--%3E%20TAB%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>偶数可压掉一半。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个合数有素因子 \\(\\le\\sqrt n\\)，故埃氏正确。线性筛的不变量：合数 \\(i\\cdot p\\) 在 \\(p=minp[i\\cdot p]\\) 时首次标记。与快速幂无关：这里没有模幂。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Atkin 筛细节。不写素数定理证明。后课默认：\\(n\\le 10^7\\) 级用线性筛表。下一课欧拉函数与莫比乌斯。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>埃氏 \\(O(n\\log\\log n)\\)；线性筛 \\(O(n)\\)。</li><li>输出 \\([1,n]\\) 素数，不是大数分解。</li><li>分段筛换空间。</li><li>出处：古典埃氏筛；CLRS 第 31 章。</li></ul>',7))])}const b=i(c,[["render",_]]);export{T as __pageData,b as default};
